fn meta_children_quality_and_acceptance_model(s: &mut HashSet<String>) -> Vec<Rc<som::SomMetaNode>> {
    vec![
        Rc::new(som::SomMetaNode { class_name: "QualityAndAcceptanceModel".to_string(), member_name: "content".to_string(), kind: som::SOM_META_KIND_CONTENT.to_string(), type_name: "String".to_string(), serialization_order: Some(0), unused: true, content_type: Some(som::SomContentTypeMeta { type_: "text".to_string(), description: "".to_string() }), ..som::SomMetaNode::default() }),
        meta_cx("SystemQualityGoals", s, meta_children_system_quality_goals, |r, c| som::SomMetaNode {
            class_name: "SystemQualityGoals".to_string(), member_name: "systemQualityGoals".to_string(), class_section_id: "SYQG".to_string(), kind: som::SOM_META_KIND_COMPLEX.to_string(), type_name: "SystemQualityGoals".to_string(), serialization_order: Some(1), doc_comment: "Quality goals and attributes.".to_string(), class_doc_comment: "11. System Quality Goals. Seeds → QAP.\n\nQuality goals selected from standard quality criteria and operationalized\nfor project-specific acceptance testing. Provides governing structure for\nall quality attributes and acceptance criteria. Seeds the QAP (Quality &\nAcceptance Plan) document where quality goals are expanded into measurable\ntargets, verification methods, and acceptance criteria.".to_string(), maps_to: "D10QualityAcceptancePlan".to_string(),
            recursive: r, children: c, ..som::SomMetaNode::default()
        }),
        meta_cx("DeliveryScopeAndAcceptance", s, meta_children_delivery_scope_and_acceptance, |r, c| som::SomMetaNode {
            class_name: "DeliveryScopeAndAcceptance".to_string(), member_name: "deliveryAcceptance".to_string(), class_section_id: "DLVA".to_string(), kind: som::SOM_META_KIND_COMPLEX.to_string(), type_name: "DeliveryScopeAndAcceptance".to_string(), serialization_order: Some(2), doc_comment: "Delivery scope and acceptance criteria.".to_string(), class_doc_comment: "14. Delivery Scope and Acceptance.".to_string(),
            recursive: r, children: c, ..som::SomMetaNode::default()
        }),
        meta_cx("Iso25010Coverage", s, meta_children_iso25010_coverage, |r, c| som::SomMetaNode {
            class_name: "Iso25010Coverage".to_string(), member_name: "iso25010Coverage".to_string(), class_section_id: "I25CV".to_string(), kind: som::SOM_META_KIND_COMPLEX.to_string(), type_name: "Iso25010Coverage".to_string(), serialization_order: Some(3), doc_comment: "ISO/IEC 25010:2023 product-quality cross-map (§5 completeness addition).".to_string(), class_doc_comment: "ISO/IEC 25010:2023 product-quality cross-map (derived).\n\nA *derived* view over the canonical quality spine: the eight\n`*Characteristic` classes under [SystemQualityGoals] are the single source\nof truth for the taxonomy (L34C-8); this cross-map does not re-declare it.\nEach entry references one of those characteristics (via the closed\n[Iso25010Characteristic] enum) and records which quality goals / NFRs\naddress it and the target metric — so coverage of any 25010:2023\ncharacteristic (e.g. compatibility, flexibility) cannot be silently missed.".to_string(),
            recursive: r, children: c, ..som::SomMetaNode::default()
        }),
    ]
}

